-- ============================================
-- LUMA — Thème 8 : MOYEN 1/3 x4 — Explorer une forêt enchantée avec des choix de chemin
-- ============================================


update scenarios set content = '{"characters": {"narrator": "narrateur", "spirit": "l''esprit de l''eau"}, "start_node": "n1", "nodes": {"n1": {"speaker": "narrator", "text": "You stand before three paths into the enchanted forest, each glowing faintly with different colors.", "text_fr": "Vous vous tenez devant trois chemins dans la forêt enchantée, chacun brillant faiblement de couleurs différentes.", "choices": [{"text": "Take the path that glows blue, shimmering like water.", "text_fr": "Prends le chemin qui brille en bleu, chatoyant comme de l''eau.", "next": "n2"}, {"text": "Take the path that glows green, pulsing gently like life itself.", "text_fr": "Prends le chemin qui brille en vert, pulsant doucement comme la vie elle-même.", "next": "n2b"}, {"text": "Take the path that glows silver, cold and mysterious.", "text_fr": "Prends le chemin qui brille en argent, froid et mystérieux.", "next": "n2c"}]}, "n2": {"speaker": "narrator", "text": "The blue path leads to a serene lake, where a water spirit watches you approach.", "text_fr": "Le chemin bleu mène à un lac serein, où un esprit de l''eau vous regarde approcher.", "choices": [{"text": "Greet the spirit respectfully and ask for guidance.", "text_fr": "Salue l''esprit respectueusement et demande conseil.", "next": "n3"}]}, "n2b": {"speaker": "narrator", "text": "The green path winds through ancient trees that seem to whisper secrets as you pass.", "text_fr": "Le chemin vert serpente à travers des arbres anciens qui semblent chuchoter des secrets à ton passage.", "choices": [{"text": "Listen closely to what the trees are whispering.", "text_fr": "Écoute attentivement ce que les arbres chuchotent.", "next": "n3b"}]}, "n2c": {"speaker": "narrator", "text": "The silver path grows colder with each step, leading toward a frozen clearing.", "text_fr": "Le chemin argenté devient de plus en plus froid à chaque pas, menant vers une clairière gelée.", "choices": [{"text": "Push forward despite the cold, curious what awaits.", "text_fr": "Avance malgré le froid, curieux de ce qui t''attend.", "next": "n3c"}]}, "n3": {"speaker": "spirit", "text": "Few show respect anymore. What do you seek in my forest, traveler?", "text_fr": "Peu montrent du respect de nos jours. Que cherchez-vous dans ma forêt, voyageur ?", "choices": [{"text": "I seek a lost artifact, said to be hidden nearby.", "text_fr": "Je cherche un artefact perdu, dit être caché à proximité.", "next": "n4"}]}, "n3b": {"speaker": "narrator", "text": "The whispers speak of an ancient guardian who tests all who enter with riddles.", "text_fr": "Les chuchotements parlent d''un gardien ancien qui teste tous ceux qui entrent avec des énigmes.", "choices": [{"text": "Continue forward, ready to face this guardian.", "text_fr": "Continue en avant, prêt à affronter ce gardien.", "next": "n4"}]}, "n3c": {"speaker": "narrator", "text": "In the clearing, you find a shard of ice pulsing with strange energy.", "text_fr": "Dans la clairière, tu trouves un éclat de glace pulsant d''une étrange énergie.", "choices": [{"text": "Reach out and touch the ice shard carefully.", "text_fr": "Tends la main et touche l''éclat de glace prudemment.", "next": "n4"}]}, "n4": {"speaker": "narrator", "text": "(Regardless of your path, all three converge near an ancient stone circle deep in the woods.)", "text_fr": "(Quel que soit ton chemin, les trois convergent près d''un cercle de pierres ancien au cœur des bois.)", "choices": [{"text": "Examine the stone circle closely for any markings.", "text_fr": "Examine le cercle de pierres de près pour des marques.", "next": "n5"}]}, "n5": {"speaker": "narrator", "text": "Ancient runes glow faintly on the stones, forming words in a forgotten language.", "text_fr": "Des runes anciennes brillent faiblement sur les pierres, formant des mots dans une langue oubliée.", "choices": [{"text": "Try to read the runes aloud, despite not understanding them.", "text_fr": "Essaie de lire les runes à voix haute, malgré le fait de ne pas les comprendre.", "next": "n6"}, {"text": "Search for a translation clue somewhere nearby.", "text_fr": "Cherche un indice de traduction quelque part à proximité.", "next": "n6b"}]}, "n6": {"speaker": "narrator", "text": "(As you speak, the runes flare brightly, and a hidden passage opens beneath the circle.)", "text_fr": "(Alors que tu parles, les runes s''illuminent vivement, et un passage caché s''ouvre sous le cercle.)", "choices": [{"text": "Descend into the passage without hesitation.", "text_fr": "Descends dans le passage sans hésiter.", "next": "n7"}]}, "n6b": {"speaker": "narrator", "text": "You find an old carving nearby depicting the same runes with their meanings.", "text_fr": "Tu trouves une vieille gravure à proximité représentant les mêmes runes avec leurs significations.", "choices": [{"text": "Use the translation to unlock the passage safely.", "text_fr": "Utilise la traduction pour déverrouiller le passage en toute sécurité.", "next": "n7"}]}, "n7": {"speaker": "narrator", "text": "The passage reveals a small chamber, and within it, a glowing artifact awaits.", "text_fr": "Le passage révèle une petite chambre, et à l''intérieur, un artefact lumineux attend.", "choices": [{"text": "Approach the artifact slowly, sensing its power.", "text_fr": "Approche-toi de l''artefact lentement, sentant son pouvoir.", "next": "n8"}]}, "n8": {"speaker": "narrator", "text": "As your hand nears it, the artifact pulses warmly, as if recognizing you.", "text_fr": "Alors que ta main s''approche, l''artefact pulse chaleureusement, comme s''il te reconnaissait.", "choices": [{"text": "Take the artifact, feeling its power merge with your own.", "text_fr": "Prends l''artefact, sentant son pouvoir fusionner avec le tien.", "next": "end_found"}]}, "end_found": {"speaker": "narrator", "text": "The forest seems to sigh with relief as the artifact finally finds its rightful bearer.", "text_fr": "La forêt semble soupirer de soulagement alors que l''artefact trouve enfin son porteur légitime.", "end": true, "ending_label": "Artefact trouvé au cœur de la forêt enchantée 🌲✨"}}}'::jsonb, is_playable = true
where title = 'Explorer une forêt enchantée avec des choix de chemin'
  and theme_id = (select id from scenario_themes where position = 8 and language_id = (select id from languages where code = 'en'));
